  const AutoGrowTextarea = ({ minHeight = 58, maxHeight = 220, onInput, style, ...props }) => {
    const ref = React.useRef(null);
    const resize = (element) => {
      if (!element) return;
      element.style.height = 'auto';
      const nextHeight = Math.max(minHeight, Math.min(element.scrollHeight, maxHeight));
      element.style.height = `${nextHeight}px`;
      element.style.overflowY = element.scrollHeight > maxHeight ? 'auto' : 'hidden';
    };
    useEffect(() => resize(ref.current), [props.value, props.defaultValue]);
    return h("textarea", {
      ...props,
      ref,
      rows: 1,
      onInput: event => { resize(event.currentTarget); if (onInput) onInput(event); },
      style: { minHeight: `${minHeight}px`, maxHeight: `${maxHeight}px`, resize: 'none', ...style }
    });
  };

  class AppErrorBoundary extends React.Component {
    constructor(props) {
      super(props);
      this.state = { error: null };
    }
    static getDerivedStateFromError(error) { return { error }; }
    componentDidCatch(error, info) { console.error('Print Ghar UI error:', error, info); }
    render() {
      if (!this.state.error) return this.props.children;
      const message = this.state.error?.message || 'An unexpected interface error occurred.';
      return h('div', { className: 'min-h-screen bg-slate-100 p-6 flex items-center justify-center' },
        h('div', { className: 'w-full max-w-xl rounded-2xl border border-rose-200 bg-white p-6 shadow-xl' }, [
          h('div', { className: 'text-xs font-black uppercase tracking-widest text-rose-600' }, 'Print Ghar recovered from an error'),
          h('h1', { className: 'mt-2 text-xl font-black text-slate-900' }, 'The app stopped one screen from rendering.'),
          h('p', { className: 'mt-2 text-sm font-semibold leading-6 text-slate-600' }, message),
          h('p', { className: 'mt-3 text-xs leading-5 text-slate-500' }, 'Your saved browser data has not been deleted. Reload the app and try the action again.'),
          h('div', { className: 'mt-5 flex flex-wrap gap-2' }, [
            h('button', { type: 'button', onClick: () => window.location.reload(), className: 'rounded-xl bg-slate-900 px-4 py-2.5 text-xs font-black text-white' }, 'Reload App'),
            h('button', { type: 'button', onClick: () => this.setState({ error: null }), className: 'rounded-xl border border-slate-200 bg-white px-4 py-2.5 text-xs font-black text-slate-700' }, 'Try to Continue')
          ])
        ])
      );
    }
  }

