  const CURRENCY_SYMBOL = 'Rs.';
  const createId = (prefix) => {
    const suffix = globalThis.crypto?.randomUUID?.() || `${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 10)}`;
    return `${prefix}-${suffix}`;
  };
  const MEDIA_DB_NAME = 'printflow_media_v1';
  const MEDIA_STORE_NAME = 'order_media';
  const ALLOWED_MEDIA_EXTENSIONS = new Set(['jpg', 'jpeg', 'png', 'webp', 'gif', 'bmp', 'heic', 'pdf', 'tif', 'tiff', 'psd', 'psb', 'ai', 'eps', 'svg', 'cdr', 'dxf', 'dwg', 'doc', 'docx', 'xls', 'xlsx', 'ppt', 'pptx', 'txt', 'zip', 'rar', '7z']);
  const getFileExtension = (name) => String(name || '').split('.').pop().toLowerCase();
  const formatFileSize = (bytes) => {
    const value = Number(bytes || 0);
    if (value < 1024) return `${value} B`;
    if (value < 1024 * 1024) return `${(value / 1024).toFixed(1)} KB`;
    return `${(value / (1024 * 1024)).toFixed(1)} MB`;
  };
  const openMediaDb = () => new Promise((resolve, reject) => {
    if (!globalThis.indexedDB) return reject(new Error('This browser does not support local file storage.'));
    const request = indexedDB.open(MEDIA_DB_NAME, 1);
    request.onupgradeneeded = () => {
      const db = request.result;
      if (!db.objectStoreNames.contains(MEDIA_STORE_NAME)) db.createObjectStore(MEDIA_STORE_NAME, { keyPath: 'id' });
    };
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error || new Error('Unable to open local file storage.'));
  });
  const mediaStore = {
    async putMany(entries) {
      if (!entries.length) return;
      const db = await openMediaDb();
      await new Promise((resolve, reject) => {
        const transaction = db.transaction(MEDIA_STORE_NAME, 'readwrite');
        const store = transaction.objectStore(MEDIA_STORE_NAME);
        entries.forEach(entry => store.put({ id: entry.id, blob: entry.file, name: entry.name, type: entry.type, size: entry.size, updatedAt: new Date().toISOString() }));
        transaction.oncomplete = resolve;
        transaction.onerror = () => reject(transaction.error || new Error('Unable to save attached files.'));
        transaction.onabort = () => reject(transaction.error || new Error('File storage was interrupted.'));
      });
      db.close();
    },
    async get(id) {
      const db = await openMediaDb();
      const record = await new Promise((resolve, reject) => {
        const request = db.transaction(MEDIA_STORE_NAME, 'readonly').objectStore(MEDIA_STORE_NAME).get(id);
        request.onsuccess = () => resolve(request.result || null);
        request.onerror = () => reject(request.error || new Error('Unable to load the attached file.'));
      });
      db.close();
      return record;
    },
    async removeMany(ids) {
      if (!ids.length) return;
      const db = await openMediaDb();
      await new Promise((resolve, reject) => {
        const transaction = db.transaction(MEDIA_STORE_NAME, 'readwrite');
        const store = transaction.objectStore(MEDIA_STORE_NAME);
        ids.forEach(id => store.delete(id));
        transaction.oncomplete = resolve;
        transaction.onerror = () => reject(transaction.error || new Error('Unable to remove attached files.'));
      });
      db.close();
    }
  };
