  window.__pgImageCache = window.__pgImageCache || new Map();
  window.__preloadImageAsDataUrl = function (url) {
    if (!url || typeof url !== 'string' || url.startsWith('data:image/')) return Promise.resolve(url);
    if (window.__pgImageCache.has(url)) return Promise.resolve(window.__pgImageCache.get(url));
    return new Promise(function (resolve) {
      const img = new Image();
      img.crossOrigin = 'anonymous';
      img.onload = function () {
        try {
          const canvas = document.createElement('canvas');
          canvas.width = img.naturalWidth || img.width;
          canvas.height = img.naturalHeight || img.height;
          const ctx = canvas.getContext('2d');
          ctx.drawImage(img, 0, 0);
          const dataUrl = canvas.toDataURL('image/png');
          window.__pgImageCache.set(url, dataUrl);
          resolve(dataUrl);
        } catch (e) {
          window.__pgImageCache.set(url, img);
          resolve(img);
        }
      };
      img.onerror = function () {
        window.__pgImageCache.set(url, url);
        resolve(url);
      };
      img.src = url;
    });
  };



