    getVendorById(id) { return this.getVendors().find(v => v.id === id || v._id === id); },

    saveVendor(vendor) {
      const list = this.getVendors();
      const clean = {
        ...vendor,
        name: String(vendor.name || '').trim(),
        phone: String(vendor.phone || '').trim(),
        email: String(vendor.email || '').trim(),
        address: String(vendor.address || '').trim(),
        notes: String(vendor.notes || '').trim()
      };
      if (!clean.name) return null;
      const now = new Date().toISOString();
      let targetVendor = null;
      if (clean.id || clean._id) {
        const targetId = clean.id || clean._id;
        const index = list.findIndex(v => v.id === targetId || v._id === targetId);
        targetVendor = { ...(index !== -1 ? list[index] : {}), ...clean, updatedAt: now };
        if (index !== -1) list[index] = targetVendor; else list.unshift(targetVendor);
      } else {
        const localId = createId('vendor');
        targetVendor = { ...clean, id: localId, localId, createdAt: now, updatedAt: now };
        list.unshift(targetVendor);
      }
      this._vendorCache = list;

      const syncId = targetVendor._id || (targetVendor.id && !String(targetVendor.id).startsWith('vendor-') ? targetVendor.id : null);
      const url = syncId ? `/api/vendors/${syncId}` : '/api/vendors';
      const method = syncId ? 'PUT' : 'POST';
      const payload = { ...targetVendor };
      if (!syncId && targetVendor.id) payload.localId = targetVendor.id;
      if (!syncId) { delete payload._id; delete payload.id; }

      fetch(url, {
        method,
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload)
      })
        .then(async res => {
          if (!res.ok) {
            const errData = await res.json().catch(() => ({}));
            throw new Error(errData.error || `HTTP ${res.status}`);
          }
          return res.json();
        })
        .then(saved => {
          if (saved && (saved._id || saved.id)) {
            const normalized = { ...saved, id: saved._id || saved.localId || saved.id };
            if (Array.isArray(this._vendorCache)) {
              const idx = this._vendorCache.findIndex(x => (normalized._id && x._id === normalized._id) || (normalized.localId && x.localId === normalized.localId) || (targetVendor.id && x.id === targetVendor.id));
              if (idx !== -1) this._vendorCache[idx] = { ...this._vendorCache[idx], ...normalized };
            }
          }
        })
        .catch(err => {
          console.error('Backend offline: Failed to save vendor to database:', err);
          if (typeof window !== 'undefined' && window.alert) {
            window.alert('Backend is offline. Unable to save vendor to database. Changes were not saved to localStorage.');
          }
        });

      return targetVendor;
    },

    removeAllDemoData() {
      // 1. Filter out demo orders
      const currentOrders = this.getOrders();
      const demoOrderPattern = /^JOB-2026-2\d{3}$/i;
      const demoClientIds = new Set(['cust-d-1', 'cust-d-2', 'cust-d-3', 'cust-d-4', 'cust-d-5', 'cust-d-6', 'cust-d-7', 'cust-d-8', 'cust-d-9', 'cust-d-10']);
      const cleanOrders = currentOrders.filter(o => !demoOrderPattern.test(o.orderNumber || '') && !demoClientIds.has(o.customerId) && !String(o.orderNumber || '').startsWith('JOB-2026-2'));
      this._orderCache = cleanOrders;
      localStorage.removeItem(STORAGE_KEYS.ORDERS);

      // 2. Filter out demo customers
      const currentCustomers = this.getCustomers();
      const cleanCustomers = currentCustomers.filter(c => !demoClientIds.has(c.id));
      this._customerCache = cleanCustomers;
      localStorage.removeItem(STORAGE_KEYS.CUSTOMERS);

      // 3. Filter out demo expenses
      const currentExpenses = this.getExpenses();
      const cleanExpenses = currentExpenses.filter(e => !['Cyan & Magenta Solvent Ink Refill', 'Frontlit Flex Media Roll 10ft', 'Delivery Van Fuel & Parking', 'Staff Tea & Production Lunch'].includes(e.title));
      this._expenseCache = cleanExpenses;
      localStorage.removeItem(STORAGE_KEYS.EXPENSES);

      localStorage.setItem(STORAGE_KEYS.DEMO_REMOVED, 'true');
      return { cleanOrdersCount: cleanOrders.length };
    },

