    const isOwnerRole = userRoleStr.includes('owner') || userRoleStr.includes('super_admin') || userRoleStr.includes('developer');
    const isReceptionRole = userRoleStr.includes('reception');
    const isOwnerOrReception = isOwnerRole || isReceptionRole;
    const isDesignerRole = userRoleStr.includes('designer') || String(loggedInUser?.jobTitle || '').toLowerCase().includes('designer');
    const isPrinterRole = userRoleStr.includes('printer') || userRoleStr.includes('finishing') || userRoleStr.includes('finisher') || String(loggedInUser?.jobTitle || '').toLowerCase().includes('printer');
