      const todayInput = storageService.dateInputValueForMode(today, dateMode);
      const monthStartInput = `${todayInput.slice(0, 8)}01`;
      setClientStatementModal({ mode, customer, dateMode, rangeMode: mode === 'csv' ? 'ALL' : 'CUSTOM', fromInput: monthStartInput, toInput: todayInput, error: '', isWorking: false });
