                    { id: 'RECEIVABLE', label: `1. Credit Still to Receive (${creditRemainingJobs.length})`, tone: 'amber' },
                    { id: 'PAYABLE', label: `2. Amount Still to Pay (${amountToPayCosts.length})`, tone: 'orange' },
                    { id: 'CREDIT_REC', label: `3. Credit Received (${creditReceivedEntries.length})`, tone: 'cyan' },
                    { id: 'EXPENSES', label: `4. Total Expenses / Purchase (${costs.length})`, tone: 'rose' }
