              if (isStockingExpense && (!linkedStockItemId || stockQuantity <= 0)) {
                alert('For a stocking expense, choose the stock product and enter the received quantity.');
                return;
              }

              let receipt = editingExpense?.receipt;
              const receiptFileInput = f.expReceipt?.files?.[0];
              if (receiptFileInput) {
                const rId = createId('rec');
                const rRecord = { id: rId, name: receiptFileInput.name, type: receiptFileInput.type, size: receiptFileInput.size, blob: receiptFileInput };
                await mediaStore.putMany([rRecord]);
                receipt = { id: rId, name: receiptFileInput.name, type: receiptFileInput.type, size: receiptFileInput.size };
              }

              try {
                await storageService.saveExpense({
                  id: editingExpense?.id,
                  expenseNumber: editingExpense?.expenseNumber,
                  title: title,
                  category,
                  vendorId: vendor?.id || '',
                  vendor: vendor?.name || '',
                  paymentMethod: paymentMethod,
                  paidBy: f.expPaidBy?.value?.trim() || '',
                  amount: amount,
                  date: expenseDate,
                  notes: f.expNotes.value.trim(),
                  receipt: receipt,
                  paymentHistory: editingExpense?.paymentHistory || [],
                  linkedPurchaseId: isStockingExpense ? linkedStockItemId : undefined,
                  stockQuantity: isStockingExpense ? stockQuantity : undefined
                });

                await storageService.loadStockFromServer();
                refresh();
                setIsExpenseModalOpen(false);
              } catch (err) {
                alert('Unable to save expense. Please check your internet connection and try again.');
              }
